import React from 'react';
import { useOutletContext } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';

const Work_P2 = () => {
  const context = useOutletContext();
  const resumeData = contextHub?.work?.data;
  
  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="work" links={["Streaming", "Collab", "Nodes", "Logs"]} />
      <div className="summary-box">
        <h3>Collaborative Workspace Session Control</h3>
        <p style={{ marginTop: '1rem' }}>{resumeData ? `Active document parsed payload cluster telemetry evaluation metric score: ${resumeData.score}%` : "No active session detected."}</p>
      </div>
    </div>
  );
};
export default Work_P2;
